"use client"

import * as React from "react"
import { Separator as SeparatorPrimitive } from "@base-ui/react/separator"

import { cn } from "@/lib/utils"

// Clicky Separator — thin line using border token
// Supports solid (default) and dotted variants

export interface SeparatorProps
  extends Omit<SeparatorPrimitive.Props, "className"> {
  className?: string
  variant?: "solid" | "dotted"
  /**
   * Accepted for API compatibility with the previous wrapper and ignored:
   * the Base UI separator is always semantic (role="separator").
   */
  decorative?: boolean
}

const Separator = React.forwardRef<HTMLDivElement, SeparatorProps>(
  (
    {
      className,
      orientation = "horizontal",
      decorative: _decorative,
      variant = "solid",
      ...props
    },
    ref
  ) => {
    if (variant === "dotted") {
      return (
        <SeparatorPrimitive
          ref={ref}
          orientation={orientation}
          className={cn(
            "shrink-0 border-0",
            orientation === "horizontal"
              ? "h-px w-full border-t border-dotted border-border bg-transparent"
              : "h-full w-px border-l border-dotted border-border bg-transparent",
            className
          )}
          {...props}
        />
      )
    }

    return (
      <SeparatorPrimitive
        ref={ref}
        orientation={orientation}
        className={cn(
          "shrink-0 bg-border",
          orientation === "horizontal" ? "h-px w-full" : "h-full w-px",
          className
        )}
        {...props}
      />
    )
  }
)
Separator.displayName = "Separator"

export { Separator }
